-- =====================================================
-- sql-skill-push: ecommerce dataset (PostgreSQL)
-- Deterministic seed-generated data. Run as a single script.
-- =====================================================

DROP TABLE IF EXISTS "categories";
DROP TABLE IF EXISTS "vendors";
DROP TABLE IF EXISTS "products";
DROP TABLE IF EXISTS "customers";
DROP TABLE IF EXISTS "orders";
DROP TABLE IF EXISTS "order_items";
DROP TABLE IF EXISTS "payments";
DROP TABLE IF EXISTS "shipments";

-- =====================================================
-- BUSINESS CONTEXT (short)
-- An online marketplace. Tables: categories, vendors, products, customers, orders, order_items, payments, shipments.
-- =====================================================

CREATE TABLE "categories" (
    "cat_id" VARCHAR(6) PRIMARY KEY,
    "cat_name" VARCHAR(40),
    "parent_cat_id" VARCHAR(6)
);

CREATE TABLE "vendors" (
    "vendor_id" VARCHAR(6) PRIMARY KEY,
    "vendor_name" VARCHAR(40),
    "country" VARCHAR(30)
);

CREATE TABLE "products" (
    "prod_id" VARCHAR(6) PRIMARY KEY,
    "prod_name" VARCHAR(60),
    "cat_id" VARCHAR(6),
    "vendor_id" VARCHAR(6),
    "unit_price" DECIMAL(10,2),
    "cost" DECIMAL(10,2),
    "is_active" SMALLINT
);

CREATE TABLE "customers" (
    "cust_id" VARCHAR(7) PRIMARY KEY,
    "first_name" VARCHAR(30),
    "last_name" VARCHAR(30),
    "email" VARCHAR(80),
    "city" VARCHAR(40),
    "country" VARCHAR(30),
    "signup_date" DATE
);

CREATE TABLE "orders" (
    "order_id" INT PRIMARY KEY,
    "order_date" DATE,
    "customer_id" VARCHAR(7),
    "status" VARCHAR(15),
    "total_amount" DECIMAL(10,2)
);

CREATE TABLE "order_items" (
    "item_id" INT PRIMARY KEY,
    "order_id" INT,
    "product_id" VARCHAR(6),
    "quantity" INT,
    "unit_price" DECIMAL(10,2)
);

CREATE TABLE "payments" (
    "payment_id" INT PRIMARY KEY,
    "order_id" INT,
    "method" VARCHAR(20),
    "amount" DECIMAL(10,2),
    "status" VARCHAR(10),
    "paid_date" DATE
);

CREATE TABLE "shipments" (
    "shipment_id" INT PRIMARY KEY,
    "order_id" INT,
    "carrier" VARCHAR(10),
    "ship_date" DATE,
    "delivery_date" DATE,
    "address" VARCHAR(80)
);

